from math import log2

# from the most work to the least
CLASSES = ["2^n", "n^3", "n^2", "n log n", "n", "log n"]


def budget_class(n):
    if n <= 60 and 2 ** n <= 10 ** 8:
        return "2^n"
    if n ** 3 <= 10 ** 8:
        return "n^3"
    if n ** 2 <= 10 ** 8:
        return "n^2"
    if n * log2(n) <= 10 ** 8:
        return "n log n"
    if n <= 10 ** 8:
        return "n"
    return "log n"

