def pair_sums_at_most(xs, k):
    a = sorted(xs)
    i, j = 0, len(a) - 1
    count = 0
    while i < j:
        if a[i] + a[j] <= k:
            count += j - i
            i += 1
        else:
            j -= 1
    return count
